$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT ShiftDate, ShiftType, ShiftStart, ShiftEnd, SourceSheet FROM ShiftEntries WHERE EmployeeId='9074334' AND ShiftDate>='2026-06-22' ORDER BY ShiftDate"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0].ToString('yyyy-MM-dd') $r[1] $r[2] $r[3] $r[4]}; $conn.Close()
